"use client";

import React, { useState, useRef } from "react";
import { motion } from "motion/react";
import { Sparkles, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

// Slab method line-segment vs AABB intersection
function lineIntersectsBox(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  left: number,
  top: number,
  right: number,
  bottom: number
): boolean {
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tmin = 0;
  let tmax = 1;

  if (Math.abs(dx) < 1e-6) {
    if (x0 < left || x0 > right) return false;
  } else {
    const tx1 = (left - x0) / dx;
    const tx2 = (right - x0) / dx;
    tmin = Math.max(tmin, Math.min(tx1, tx2));
    tmax = Math.min(tmax, Math.max(tx1, tx2));
  }

  if (Math.abs(dy) < 1e-6) {
    if (y0 < top || y0 > bottom) return false;
  } else {
    const ty1 = (top - y0) / dy;
    const ty2 = (bottom - y0) / dy;
    tmin = Math.max(tmin, Math.min(ty1, ty2));
    tmax = Math.min(tmax, Math.max(ty1, ty2));
  }

  return tmin <= tmax && tmax >= 0 && tmin <= 1;
}

export interface BobbleHoverProps
  extends React.HTMLAttributes<HTMLDivElement> {
  rows?: number;
  cols?: number;
}

export function BobbleHover({
  rows = 5,
  cols = 7,
  className,
  ...props
}: BobbleHoverProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const prevPointRef = useRef<{ x: number; y: number } | null>(null);
  const [activeTiles, setActiveTiles] = useState<Record<number, number>>({});

  const totalTiles = rows * cols;

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const containerRect = containerRef.current.getBoundingClientRect();
    const currentX = e.clientX - containerRect.left;
    const currentY = e.clientY - containerRect.top;

    const prevX = prevPointRef.current ? prevPointRef.current.x : currentX;
    const prevY = prevPointRef.current ? prevPointRef.current.y : currentY;

    prevPointRef.current = { x: currentX, y: currentY };

    const tileElements = containerRef.current.querySelectorAll("[data-tile-index]");
    const now = Date.now();
    const newlyActive: Record<number, number> = {};

    tileElements.forEach((el) => {
      const idx = Number(el.getAttribute("data-tile-index"));
      const r = el.getBoundingClientRect();
      const left = r.left - containerRect.left;
      const top = r.top - containerRect.top;
      const right = left + r.width;
      const bottom = top + r.height;

      if (lineIntersectsBox(prevX, prevY, currentX, currentY, left, top, right, bottom)) {
        newlyActive[idx] = now;
      }
    });

    if (Object.keys(newlyActive).length > 0) {
      setActiveTiles((prev) => ({ ...prev, ...newlyActive }));
    }
  };

  const handlePointerLeave = () => {
    prevPointRef.current = null;
  };

  const handleReset = () => {
    setActiveTiles({});
  };

  return (
    <div
      data-slot="bobble-hover"
      className={cn(
        "flex flex-col items-center justify-center gap-6 p-8 w-full max-w-lg mx-auto select-none rounded-3xl border border-neutral-200 bg-white dark:border-neutral-800 dark:bg-neutral-950 shadow-2xl",
        className
      )}
      {...props}
    >
      <div className="flex items-center justify-between w-full px-2">
        <div className="flex items-center gap-2">
          <Sparkles className="h-4 w-4 text-pink-500" />
          <span className="text-xs font-bold uppercase tracking-wider text-neutral-800 dark:text-neutral-200">
            Continuous Collision Hover
          </span>
        </div>
        <button
          type="button"
          onClick={handleReset}
          className="flex items-center gap-1 text-xs font-semibold text-neutral-500 hover:text-neutral-900 dark:hover:text-neutral-100 cursor-pointer"
        >
          <RotateCcw className="h-3 w-3" />
          <span>Clear Trail</span>
        </button>
      </div>

      {/* Interactive Slab Matrix Grid */}
      <div
        ref={containerRef}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
        className="grid gap-2.5 p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-800"
        style={{
          gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
        }}
      >
        {Array.from({ length: totalTiles }).map((_, index) => {
          const isHit = !!activeTiles[index];
          return (
            <motion.div
              key={index}
              data-tile-index={index}
              animate={
                isHit
                  ? {
                      scale: [1, 1.35, 1],
                      backgroundColor: [
                        "#ec4899",
                        "#a855f7",
                        "#3b82f6",
                        "#ec4899",
                      ],
                    }
                  : { scale: 1 }
              }
              transition={{
                type: "spring",
                stiffness: 400,
                damping: 20,
              }}
              className={cn(
                "h-10 w-10 rounded-xl transition-colors cursor-crosshair flex items-center justify-center shadow-xs",
                isHit
                  ? "bg-pink-500 text-white shadow-[0_0_12px_rgba(236,72,153,0.5)]"
                  : "bg-neutral-200/80 hover:bg-neutral-300 dark:bg-neutral-800 dark:hover:bg-neutral-700"
              )}
            />
          );
        })}
      </div>

      <p className="text-xs text-muted-foreground font-mono text-center">
        Swipe as fast as you want across the matrix. Zero frames or cells are ever skipped.
      </p>
    </div>
  );
}
